import{_ as t,o as r,c as a,a2 as s}from"./chunks/framework.BxGh02fV.js";const f=JSON.parse('{"title":"Avec un agent","description":"","frontmatter":{"title":"Avec un agent"},"headers":[],"relativePath":"agent/index.md","filePath":"agent/index.md"}'),o={name:"agent/index.md"};function n(l,e,i,d,u,c){return r(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="avec-un-agent" tabindex="-1">Avec un agent <a class="header-anchor" href="#avec-un-agent" aria-label="Permalink to &quot;Avec un agent&quot;">​</a></h1><p>Votre agent IA pilote Effortless par ses verbes MCP : il lit l&#39;état du projet, crée, met à jour, vérifie. Vous décidez, l&#39;agent exécute. L&#39;application montre le même projet, au même moment : tout ce que l&#39;agent fait se voit à l&#39;écran (voir le <a href="/Effortless/guide/">guide de l&#39;application</a>).</p><p>Vous parlez à votre agent en langage naturel. Chaque page de ce guide part de ce que vous lui demandez, puis dit ce qu&#39;il fait, ce que vous obtenez, et ce qui se passe quand un appel est refusé.</p><h2 id="compatibilite" tabindex="-1">Compatibilité <a class="header-anchor" href="#compatibilite" aria-label="Permalink to &quot;Compatibilité&quot;">​</a></h2><p>Effortless ne cible pas un agent en particulier. Aujourd&#39;hui, les agents qui s&#39;appuient sur des modèles de pointe (LLM « frontier ») sont les plus à même de l&#39;exploiter — Claude Code, Codex ou Antigravity par exemple. L&#39;intégration à opencode est en cours ; selon le modèle utilisé, un fonctionnement similaire n&#39;est pas garanti.</p><h2 id="travailler-au-mieux-l-agent-ouvert-a-la-racine-du-projet" tabindex="-1">Travailler au mieux : l&#39;agent ouvert à la racine du projet <a class="header-anchor" href="#travailler-au-mieux-l-agent-ouvert-a-la-racine-du-projet" aria-label="Permalink to &quot;Travailler au mieux : l&#39;agent ouvert à la racine du projet&quot;">​</a></h2><p>La meilleure expérience d&#39;Effortless s&#39;obtient avec un <strong>agent en ligne de commande</strong> — Claude Code, Codex ou Antigravity par exemple — dont la session est ouverte <strong>à la racine du projet</strong>, c&#39;est-à-dire dans le dossier qui contient <code>effortless.json</code> et <code>.effortless/</code>.</p><p>Pourquoi la racine :</p><ul><li>le serveur MCP d&#39;Effortless reconnaît le projet à partir du dossier où la session a été ouverte. Ouverte ailleurs, il ne trouve pas de projet, et ses verbes le disent dans leur refus ;</li><li>c&#39;est à la racine que vivent <code>AGENTS.md</code> et <code>CLAUDE.md</code>, que l&#39;agent lit au démarrage pour connaître les verbes et la méthode ;</li><li>l&#39;agent travaille directement dans le code du projet, là où vont ses modifications et ses commits.</li></ul><p>En pratique, dans un terminal :</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Projets/mon-projet</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # le dossier qui contient effortless.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # ou codex, ou la commande de votre agent</span></span></code></pre></div><p>Puis parlez-lui : « Où en est le projet ? » ou « Démarre une story pour le formulaire de devis ». Gardez l&#39;application Effortless ouverte à côté : vous y voyez, en direct, ce que fait l&#39;agent.</p><p>D&#39;autres façons de travailler restent confortables :</p><ul><li><strong>le terminal intégré de VS Code</strong> (ou d&#39;un autre éditeur) : ouvrez le dossier du projet (<strong>Fichier › Ouvrir le dossier</strong>), puis un nouveau terminal — il s&#39;ouvre déjà à la racine. Lancez-y votre agent ;</li><li><strong>l&#39;extension ou le client de bureau de votre agent</strong>, du moment que la session vise le dossier du projet.</li></ul><p>Si l&#39;agent répond qu&#39;aucun projet Effortless n&#39;est trouvé, c&#39;est presque toujours que la session n&#39;a pas été ouverte à la racine : fermez-la, placez-vous dans le dossier du projet, et relancez-la.</p><h2 id="connecter-un-agent" tabindex="-1">Connecter un agent <a class="header-anchor" href="#connecter-un-agent" aria-label="Permalink to &quot;Connecter un agent&quot;">​</a></h2><p>Deux voies, qui font le même travail :</p><ul><li><strong>Depuis l&#39;application</strong> : <strong>Préférences</strong>, catégorie <strong>MCP &amp; Skills</strong>. Sélectionnez les assistants détectés, puis <strong>Déployer</strong> (voir <a href="/Effortless/guide/preferences.html">Profil et préférences</a>).</li><li><strong>Par l&#39;agent</strong> : <a href="/Effortless/reference/mcp/installation.html#deploy"><code>effortless_deploy</code></a>. Sans paramètre, il vise tous les clients détectés sur la machine.</li></ul><p>Le déploiement pose :</p><ul><li>la configuration du serveur MCP Effortless dans chaque client détecté ;</li><li>un guide global Effortless, entre marqueurs, dans les fichiers d&#39;instructions des agents visés (<code>~/.claude/CLAUDE.md</code>, <code>~/.config/opencode/AGENTS.md</code>) : le reste de ces fichiers n&#39;est pas touché ;</li><li>pour Claude Code, une barre d&#39;état Effortless (<code>~/.claude/effortless/statusline.mjs</code>). Si vous avez déjà votre propre barre d&#39;état, elle est conservée : le compte rendu du déploiement vous donne la ligne à poser pour adopter celle d&#39;Effortless.</li></ul><p>Après un déploiement, relancez ou reconnectez le serveur dans votre agent pour qu&#39;il voie les verbes.</p><h2 id="dans-un-projet" tabindex="-1">Dans un projet <a class="header-anchor" href="#dans-un-projet" aria-label="Permalink to &quot;Dans un projet&quot;">​</a></h2><p><a href="/Effortless/reference/mcp/installation.html#init"><code>effortless_init</code></a> et <a href="/Effortless/reference/mcp/pilotage.html#features"><code>effortless_features</code></a> (avec <code>write_doc: true</code>) posent deux fichiers à la racine du projet, entre marqueurs, sans toucher au reste :</p><ul><li><code>AGENTS.md</code> : le registre complet des verbes, dérivé du moteur. C&#39;est ce que l&#39;agent lit pour savoir quoi appeler.</li><li><code>CLAUDE.md</code> : il importe <code>AGENTS.md</code> (ligne <code>@AGENTS.md</code>), pour les agents qui lisent ce fichier-là.</li></ul><p>Ne les éditez pas entre les marqueurs : la section est régénérée.</p><h2 id="modes-de-travail" tabindex="-1">Modes de travail <a class="header-anchor" href="#modes-de-travail" aria-label="Permalink to &quot;Modes de travail&quot;">​</a></h2><p>Le mode se règle par projet, dans <strong>Réglages du projet</strong> (<a href="/Effortless/guide/settings.html">voir l&#39;écran</a>) ou en le demandant à l&#39;agent (<a href="/Effortless/reference/mcp/pilotage.html#mode-set"><code>effortless_mode_set</code></a>).</p><table tabindex="0"><thead><tr><th>Mode</th><th>Ce que l&#39;agent peut faire</th></tr></thead><tbody><tr><td><strong>Full</strong></td><td>Avance de façon autonome, sans validation intermédiaire.</td></tr><tr><td><strong>Semi-auto</strong></td><td>Propose, et vous validez les jalons clés. Les outils d&#39;exécution sont désactivés : la boucle équipe, l&#39;exécution d&#39;une livraison, la promotion publique. Le déplacement du code vers <code>codebase/&lt;stack&gt;/</code> ne s&#39;exécute pas non plus.</td></tr><tr><td><strong>Tutoré</strong></td><td>Pas à pas pédagogique : chaque étape est expliquée et confirmée.</td></tr></tbody></table><h2 id="vous-gardez-la-main" tabindex="-1">Vous gardez la main <a class="header-anchor" href="#vous-gardez-la-main" aria-label="Permalink to &quot;Vous gardez la main&quot;">​</a></h2><p>Les actions sortantes ou irréversibles (commit, push, tag, release, publication) ne sont faites par l&#39;agent qu&#39;<strong>après votre accord explicite</strong>.</p><p>Quand un appel est refusé, le refus dit deux choses : un <code>code</code> (la cause) et un <code>act</code> (ce qu&#39;il faut faire pour que le même appel réussisse : un autre verbe, ou un argument à corriger). Votre agent s&#39;en sert directement ; chaque page de parcours liste les refus réels de ses verbes.</p><h2 id="les-parcours" tabindex="-1">Les parcours <a class="header-anchor" href="#les-parcours" aria-label="Permalink to &quot;Les parcours&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Pour</th></tr></thead><tbody><tr><td><a href="/Effortless/agent/demarrer.html">Démarrer</a></td><td>Créer un projet, reprendre un projet existant, déployer.</td></tr><tr><td><a href="/Effortless/agent/faire-le-point.html">Faire le point</a></td><td>Savoir où en est le projet et ce qui vous attend.</td></tr><tr><td><a href="/Effortless/agent/cadrer.html">Cadrer</a></td><td>Poser décisions, questions et cadrage.</td></tr><tr><td><a href="/Effortless/agent/piloter.html">Piloter</a></td><td>Épics, stories, tâches et phases.</td></tr><tr><td><a href="/Effortless/agent/evolutions.html">Évolutions</a></td><td>Noter, ordonner et graduer les idées.</td></tr><tr><td><a href="/Effortless/agent/normes.html">Normes</a></td><td>Normes de développement, source partagée, amendements.</td></tr><tr><td><a href="/Effortless/agent/code.html">Code</a></td><td>Stacks, modèles, modules, dérive.</td></tr><tr><td><a href="/Effortless/agent/qualite.html">Qualité</a></td><td>Mesurer, valider, réparer.</td></tr><tr><td><a href="/Effortless/agent/livrer.html">Livrer</a></td><td>Planifier et exécuter une livraison.</td></tr><tr><td><a href="/Effortless/agent/documentation.html">Documentation</a></td><td>Documents du projet, recherche, documentation utilisateur.</td></tr><tr><td><a href="/Effortless/agent/boucle-equipe.html">Boucle équipe</a></td><td>Faire travailler analyste, développeur et QA en relais.</td></tr></tbody></table><h2 id="reference" tabindex="-1">Référence <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Référence&quot;">​</a></h2><p>Chaque verbe, ses paramètres et sa portée : <a href="/Effortless/reference/mcp/">Référence MCP</a>.</p>`,35)])])}const m=t(o,[["render",n]]);export{f as __pageData,m as default};
